// pages/platform.page.ts
// Generated by QA-AI-Framework — Playwright Automation Agent
// Module: Platform / Cross-Cutting Technical (PLATFORM)
// Application: IGZ Marquis Hunting App ("RanchOps Pro")
//
// Design choice: PLATFORM's test cases are cross-cutting (pagination spans Bookings,
// Ranches, Guides/Staff, Harvest Logs, Invoices lists; generic field validation spans
// multiple forms). Rather than duplicating pagination locators inside every module's
// own Page Object, this file holds ONE shared, parameterized set of pagination locators
// and helpers (confirmed structurally identical across all 3 list views independently
// re-verified this session — Bookings, Ranches, Guests; see docs/dom-snapshots/platform.json)
// plus a generic field-validation helper reused by any module's form. Module-specific
// Page Objects (booking.page.ts, guest.page.ts, ranch.page.ts, etc.) may still expose their
// own thin re-export of `paginationSummaryText` for convenience, but the canonical
// pagination behavior lives here.

import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export class PlatformPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  get paginationSummaryText(): Locator {
    return this.page.getByText(/Showing \d+ to \d+ of \d+ results/);
  }

  get perPageLabel(): Locator {
    return this.page.getByText('per page');
  }

  get perPageSizeDropdown(): Locator {
    return this.perPageLabel.locator('..').getByRole('combobox');
  }

  get previousPageButton(): Locator {
    // First button in the pagination control cluster (disabled on page 1).
    return this.paginationSummaryText.locator('..').locator('..').getByRole('button').first();
  }

  get nextPageButton(): Locator {
    // Last button in the pagination control cluster (disabled on last page).
    return this.paginationSummaryText.locator('..').locator('..').getByRole('button').last();
  }

  getPageNumberButton(pageNumber: number | string): Locator {
    return this.page.getByRole('button', { name: String(pageNumber), exact: true });
  }

  // ==================== Validations ====================

  async assertPaginationControlVisible(): Promise<void> {
    await expect(this.paginationSummaryText).toBeVisible();
    await expect(this.perPageSizeDropdown).toBeVisible();
  }

  async assertResultsSummaryFormat(): Promise<void> {
    await expect(this.paginationSummaryText).toHaveText(/Showing \d+ to \d+ of \d+ results/);
  }

  /** Asserts the DOM disabled/aria-disabled state rather than a raw CSS check, per ui-standards.md. */
  async assertPreviousDisabledOnFirstPage(): Promise<void> {
    await expect(this.previousPageButton).toBeDisabled();
  }

  async assertNextDisabledOnLastPage(): Promise<void> {
    await expect(this.nextPageButton).toBeDisabled();
  }

  async assertNoHorizontalOverflow(): Promise<void> {
    const hasOverflow = await this.page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
    );
    expect(hasOverflow).toBeFalsy();
  }

  /** Generic field-level format-validation assertion reused across modules (FR-PLATFORM-003). */
  async assertFieldValidationErrorVisible(fieldLocator: Locator): Promise<void> {
    const container = this.page.locator('div').filter({ has: fieldLocator }).last();
    await expect(container.getByText(/required|invalid|must|format/i)).toBeVisible();
  }

  // ==================== Actions ====================

  async goToNextPage(): Promise<void> {
    await this.withHeal(this.nextPageButton, (l) => l.click(), 'Pagination Next Button');
    await this.waitForLoadingToComplete();
  }

  async goToPreviousPage(): Promise<void> {
    await this.withHeal(this.previousPageButton, (l) => l.click(), 'Pagination Previous Button');
    await this.waitForLoadingToComplete();
  }

  async goToPage(pageNumber: number | string): Promise<void> {
    await this.withHeal(this.getPageNumberButton(pageNumber), (l) => l.click(), `Pagination Page Button (${pageNumber})`);
    await this.waitForLoadingToComplete();
  }

  async goToLastPage(): Promise<void> {
    // Repeated Next clicks until the Next button becomes disabled — avoids hardcoding
    // a specific page-count assumption per list view (counts differ: Bookings 26,
    // Ranches 10, Guests 21 pages at the default page size of 10 — see platform.json).
    let guard = 0;
    while (!(await this.nextPageButton.isDisabled()) && guard < 50) {
      await this.goToNextPage();
      guard += 1;
    }
  }

  async setPageSize(size: '10' | '20' | '50' | '100'): Promise<void> {
    await this.withHeal(this.perPageSizeDropdown, (l) => l.selectOption(size), `Per-Page Size (${size})`);
    await this.waitForLoadingToComplete();
  }

  /** Rapidly clicks Next N times to assert robustness (no skip/duplicate/corrupt state — TC_GEN_PLATFORM_002). */
  async rapidClickNext(times: number): Promise<void> {
    for (let i = 0; i < times; i += 1) {
      await this.withHeal(this.nextPageButton, (l) => l.click(), 'Pagination Next Button (rapid)');
    }
    await this.waitForLoadingToComplete();
  }
}
